using EventLensAI.Application.Common;using EventLensAI.Application.DTOs.Events;using EventLensAI.Application.Services;using EventLensAI.Domain.Enums;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace EventLensAI.API.Controllers;
[ApiController,Authorize,Route("api/events/{eventId:guid}/branding")]public sealed class EventBrandController(IEventBrandService service):ControllerBase{[HttpGet]public async Task<ActionResult<ApiResponse<EventBrandDto>>>Get(Guid eventId,CancellationToken ct)=>Ok(ApiResponse<EventBrandDto>.Ok(await service.GetAsync(eventId,ct)));[HttpPut]public async Task<ActionResult<ApiResponse<EventBrandDto>>>Put(Guid eventId,UpdateEventBrandRequest r,CancellationToken ct)=>Ok(ApiResponse<EventBrandDto>.Ok(await service.UpdateAsync(eventId,r,ct),"Event branding updated."));}
[ApiController,Authorize,Route("api/events/{eventId:guid}/experience")]public sealed class EventExperienceController(IEventExperienceService service):ControllerBase{[HttpGet]public async Task<ActionResult<ApiResponse<EventExperienceDto>>>Get(Guid eventId,CancellationToken ct)=>Ok(ApiResponse<EventExperienceDto>.Ok(await service.GetAsync(eventId,ct)));[HttpPut]public async Task<ActionResult<ApiResponse<EventExperienceDto>>>Put(Guid eventId,UpdateExperienceRequest r,CancellationToken ct)=>Ok(ApiResponse<EventExperienceDto>.Ok(await service.UpdateAsync(eventId,r,ct),"Guest experience updated."));}
[ApiController,Authorize,Route("api/events/{eventId:guid}/assets")]public sealed class EventAssetsController(IEventAssetService service):ControllerBase{[HttpGet]public async Task<ActionResult<ApiResponse<IReadOnlyList<EventAssetDto>>>>List(Guid eventId,CancellationToken ct)=>Ok(ApiResponse<IReadOnlyList<EventAssetDto>>.Ok(await service.ListAsync(eventId,ct)));[HttpPost,Consumes("multipart/form-data")]public async Task<ActionResult<ApiResponse<EventAssetDto>>>Upload(Guid eventId,[FromForm]EventAssetType assetType,[FromForm]string displayName,[FromForm]int displayOrder,IFormFile file,CancellationToken ct){await using var s=file.OpenReadStream();var x=await service.UploadAsync(eventId,new(assetType,displayName,displayOrder,file.FileName,file.ContentType,file.Length,s),ct);return Ok(ApiResponse<EventAssetDto>.Ok(x,"Event asset uploaded."));}[HttpDelete("{assetId:guid}")]public async Task<ActionResult<ApiResponse<object>>>Delete(Guid eventId,Guid assetId,CancellationToken ct){await service.ArchiveAsync(eventId,assetId,ct);return Ok(ApiResponse<object>.Ok(new{},"Event asset archived."));}}
[ApiController,Authorize,Route("api/events/{eventId:guid}/sponsors")]public sealed class EventSponsorsController(IEventSponsorService service):ControllerBase{[HttpGet]public async Task<ActionResult<ApiResponse<IReadOnlyList<SponsorDto>>>>List(Guid eventId,CancellationToken ct)=>Ok(ApiResponse<IReadOnlyList<SponsorDto>>.Ok(await service.ListAsync(eventId,ct)));[HttpPost]public async Task<ActionResult<ApiResponse<SponsorDto>>>Create(Guid eventId,CreateSponsorRequest r,CancellationToken ct)=>Ok(ApiResponse<SponsorDto>.Ok(await service.CreateAsync(eventId,r,ct),"Sponsor created."));[HttpPut("{id:guid}")]public async Task<ActionResult<ApiResponse<SponsorDto>>>Update(Guid eventId,Guid id,UpdateSponsorRequest r,CancellationToken ct)=>Ok(ApiResponse<SponsorDto>.Ok(await service.UpdateAsync(eventId,id,r,ct),"Sponsor updated."));[HttpDelete("{id:guid}")]public async Task<ActionResult<ApiResponse<object>>>Delete(Guid eventId,Guid id,CancellationToken ct){await service.ArchiveAsync(eventId,id,ct);return Ok(ApiResponse<object>.Ok(new{},"Sponsor archived."));}}
